delimiter $$
CREATE FUNCTION calculate_project_completion(employee_ids INT[])
RETURNS JSON
BEGIN
    DECLARE output JSON DEFAULT '{"approach": "Calculate the average hours worked on projects by all employees", "allocations": {';

    WITH average_hours AS (
        SELECT m.employee, AVG(m.hours) as avg_hours FROM hours_by_month m GROUP BY m.employee)

    , allocation AS (
        SELECT a.employee, (a.avg_hours * 100000 / (SELECT MAX(avg_hours) FROM average_hours)) as share FROM average_hours a)

    SELECT GROUP_CONCAT(CONCAT('"E', employee, '": ', ROUND(share, 2)), ', ') INTO output
    FROM allocation a
    ORDER BY employee;

    SET output = JSON_UNQUOTE(JSON_REMOVE(output, '$[-1]'));

    SET output = CONCAT(output, '}}');

    RETURN output;
END
$$

SELECT calculate_project_completion(ARRAY.FILL(E0, E25));
DELIMITER ;

